var sb = new System.Text.StringBuilder();
foreach (var bc in UnityEngine.Object.FindObjectsByType<BoxCollider>(FindObjectsInactive.Include, FindObjectsSortMode.None))
{
    var s = bc.transform.lossyScale;
    if (s.x < 0 || s.y < 0 || s.z < 0 || bc.size.x < 0 || bc.size.y < 0 || bc.size.z < 0)
    {
        var t = bc.transform;
        var path = new System.Text.StringBuilder(t.name);
        while (t.parent != null) { t = t.parent; path.Insert(0, t.name + "/"); }
        sb.AppendLine($"{bc.gameObject.name} | path={path} | lossyScale={bc.transform.lossyScale} | size={bc.size}");
    }
}
return sb.ToString();
